import sys; sys.path.insert(0, '.')
from solution import count_good_sequences as f
from math import comb
def dM(n, M):
    r=1; p=2
    while p*p<=n:
        e=0
        while n%p==0: n//=p; e+=1
        r*=comb(e+M-1,e); p+=1
    if n>1: r*=M
    return r
def sig(n): return sum(d for d in range(1,n+1) if n%d==0)
for N in list(range(1,120))+[500,997]:
    for M in (1,2,3,7):
        b=sum(dM(n,M) for n in range(1,N+1) if sig(n)%3==0)%998244353
        assert f(N,M)==b,(N,M,f(N,M),b)
print("ok")
EOF
python3 $TMPDIR/brute.py && time python3 -c "from solution import *; print(count_good_sequences(10**10,10**5))"

